from itertools import combinations
from typing import Dict, List, Sequence, Tuple
Puzzle = List[List[Tuple[int, int]]]

def pins_all_consistently(S: Sequence[List[Tuple[int, int]]], n: int) -> bool:
    forced: Dict[int, int] = {}
    for c in S:
        for i, p in c:
            v = 1 - p                      # falsifying (i,p) forces a_i = 1 - p
            if forced.setdefault(i, v) != v:
                return False               # conflict: F_S is empty
    return len(forced) == n               # |F_S| = 2^(n - #forced) is odd iff full

def parity_by_pinning(P: Puzzle, n: int) -> int:
    total = 0
    for r in range(len(P) + 1):
        for S in combinations(P, r):
            total += pins_all_consistently(S, n)
    return total % 2

if __name__ == "__main__":
    P = [[(0, 1), (1, 1)], [(1, 0), (2, 1)]]
    print(parity_by_pinning(P, 3))        # 0, matching #P = 4

