from itertools import product
from typing import List, Tuple
Puzzle = List[List[Tuple[int, int]]]

def assemblies(P: Puzzle, n: int) -> List[Tuple[int, ...]]:
    return [a for a in product((0, 1), repeat=n)
            if all(any(a[i] == p for i, p in c) for c in P)]

def mask_symmetry_group(P: Puzzle, n: int) -> List[Tuple[int, ...]]:
    A = set(assemblies(P, n))
    return [mu for mu in product((0, 1), repeat=n)
            if {tuple((x + y) % 2 for x, y in zip(a, mu)) for a in A} == A]

def two_adic_certificate(P: Puzzle, n: int) -> Tuple[int, int]:
    """Return (k, #P) with 2^k = |H_P| dividing #P."""
    H = mask_symmetry_group(P, n)
    k = len(H).bit_length() - 1
    c = len(assemblies(P, n))
    assert len(H) == 2 ** k and c % len(H) == 0
    return k, c

if __name__ == "__main__":
    print(two_adic_certificate([[(0, 1), (0, 0)], [(1, 1)]], 3))   # (2, 4): x1, x3 free
